package studio.jiayu.neo;
import org.json.*;
import java.io.*;
final class ProjectEditsTest {
 static JSONArray checks;interface Attempt{void run()throws Exception;}
 static void ok(boolean x,String n)throws Exception{if(!x)throw new Exception(n);checks.put(n);}
 static void reject(String n,Attempt f)throws Exception{boolean fail=false;try{f.run();}catch(Exception e){fail=true;}ok(fail,n);}
 static void run(MainActivity a){JSONObject report=new JSONObject();checks=new JSONArray();try{
 JSONObject base=new JSONObject().put("index.html","original").put("app.js","let a=1;").put("keep.txt","preserve");JSONObject p=new JSONObject().put("id","fixture").put("name","项目").put("files",base).put("tasks",new JSONArray().put("keep"));String before=p.toString();
 JSONObject changes=new JSONObject().put("app.js","let a=2;").put("new.css","body{}");JSONObject out=ProjectEdits.apply(p,base,changes,"test");
 ok(p.toString().equals(before),"input untouched");ok(out.getJSONObject("files").getString("app.js").equals("let a=2;"),"existing file updated");ok(out.getJSONObject("files").getString("new.css").equals("body{}"),"new file created");ok(out.getJSONObject("files").getString("keep.txt").equals("preserve"),"unlisted file preserved");ok(out.getJSONArray("tasks").toString().equals(p.getJSONArray("tasks").toString()),"project metadata preserved");ok(ProjectEdits.same(out.getJSONArray("snapshots").getJSONObject(0).getJSONObject("files"),base),"complete recovery snapshot");
 final JSONObject stale=out;reject("stale baseline rejected",()->ProjectEdits.apply(stale,base,changes,"test"));reject("path traversal rejected",()->ProjectEdits.apply(p,base,new JSONObject().put("../bad.js","oops"),"test"));reject("nested path rejected",()->ProjectEdits.apply(p,base,new JSONObject().put("src/a.js","oops"),"test"));reject("binary extension rejected",()->ProjectEdits.apply(p,base,new JSONObject().put("a.apk","oops"),"test"));reject("nontext rejected",()->ProjectEdits.apply(p,base,new JSONObject().put("a.js",123),"test"));reject("entry deletion rejected",()->ProjectEdits.apply(p,base,new JSONObject().put("index.html",JSONObject.NULL),"test"));reject("unknown deletion rejected",()->ProjectEdits.apply(p,base,new JSONObject().put("none.js",JSONObject.NULL),"test"));
 JSONObject deleted=ProjectEdits.apply(p,base,new JSONObject().put("app.js",JSONObject.NULL),"test");ok(!deleted.getJSONObject("files").has("app.js"),"explicit deletion works");
 JSONObject ordered=new JSONObject().put("keep.txt","preserve").put("app.js","let a=1;").put("index.html","original");ok(ProjectEdits.same(base,ordered),"key ordering independent");ok(ProjectEdits.parse("```json\n{\"files\":{\"a.js\":\"x\"}}\n```").getString("a.js").equals("x"),"fenced JSON accepted");reject("prose rejected",()->ProjectEdits.parse("some advice"));reject("missing files rejected",()->ProjectEdits.parse("{\"summary\":\"advice\"}"));
 JSONObject many=new JSONObject();for(int i=0;i<41;i++)many.put("f"+i+".txt","x");reject("file count limit",()->ProjectEdits.apply(p,base,many,"test"));StringBuilder big=new StringBuilder();for(int i=0;i<450001;i++)big.append('x');reject("size limit",()->ProjectEdits.apply(p,base,new JSONObject().put("large.txt",big.toString()),"test"));
 for(int i=0;i<8;i++)out=ProjectEdits.apply(out,out.getJSONObject("files"),new JSONObject().put("app.js","revision"+i),"test");ok(out.getJSONArray("snapshots").length()==5,"five snapshot retention");report.put("result","PASS");
 }catch(Exception e){try{report.put("result","FAIL").put("error",e.toString());}catch(Exception ignored){}}try{report.put("count",checks.length()).put("checks",checks);try(FileOutputStream f=new FileOutputStream(new File(a.getFilesDir(),"edits-selftest.json"))){f.write(report.toString(2).getBytes("UTF-8"));}}catch(Exception ignored){}}
}
